={{ (function() {
  const b = $json.body || {};
  const lines = [];

  lines.push(`🔔 *${b.formulario || 'Novo Lead Comercial'}*`);
  lines.push('');

  const name = b.name || b.nome;
  if (name) lines.push(`👤 *Nome:* ${name}`);

  const empresa = b.businessName || b.empresa;
  if (empresa) lines.push(`🏢 *Empresa:* ${empresa}`);

  if (b.email) lines.push(`📧 *E-mail:* ${b.email}`);

  const rawPhone = b.phone || b.whatsapp;
  if (rawPhone) {
    const digits = String(rawPhone).replace(/\D/g, '');
    const cleanPhone = digits.length > 0 ? (digits.length <= 11 ? '55' + digits : digits) : '';
    const waLink = cleanPhone ? `https://wa.me/${cleanPhone}` : rawPhone;
    lines.push(`📱 *WhatsApp:* ${waLink}`);
  }

  if (b.necessidade) lines.push(`🎯 *Necessidade:* ${b.necessidade}`);

  const segmento = b.segment || b.segmento;
  if (segmento) lines.push(`🍕 *Segmento:* ${segmento}`);

  if (b.city || b.state) {
    const loc = [b.city, b.state].filter(Boolean).join(' - ');
    if (loc) lines.push(`📍 *Localização:* ${loc}`);
  }

  if (b.locations && Number(b.locations) > 1) lines.push(`🏪 *Unidades:* ${b.locations}`);

  if (b.monthlyDeliveryOrders && b.monthlyDeliveryOrders !== 'N/A') lines.push(`📦 *Pedidos/Mês:* ${b.monthlyDeliveryOrders}`);

  if (b.platforms) {
    const platStr = Array.isArray(b.platforms) ? b.platforms.join(', ') : b.platforms;
    if (platStr && platStr !== 'N/A') lines.push(`🛵 *Plataformas:* ${platStr}`);
  }

  if (b.preferredContact && b.preferredContact !== 'whatsapp') lines.push(`💬 *Contato Preferencial:* ${b.preferredContact}`);

  const msg = b.mensagem || b.currentPain;
  if (msg && msg !== 'N/A') lines.push(`📝 *Mensagem:* ${msg}`);

  if (b.origem) lines.push(`🌐 *Origem:* ${b.origem}`);

  if (b.id && b.id !== 'N/A') lines.push(`🆔 *ID:* \\`${b.id}\\``);

  return lines.join('\n');
})() }}
